import{_ as e,C as r,o,c as i,E as l,a2 as s}from"./chunks/framework.DzI0iiKn.js";const n="/xuexitong-tutorial/images/settings.png",m=JSON.parse('{"title":"二、使用教程","description":"","frontmatter":{"title":"二、使用教程"},"headers":[],"relativePath":"guide/usage.md","filePath":"guide/usage.md","lastUpdated":1792075685000}'),h={name:"guide/usage.md"};function d(c,a,p,u,g,_){const t=r("PageHero");return o(),i("div",null,[l(t,{index:"02",icon:"🎯",title:"使用教程",subtitle:"从启动程序到开始刷课，逐项说明设置页面的每一个选项"}),a[0]||(a[0]=s('<h2 id="省流版" tabindex="-1">省流版 <a class="header-anchor" href="#省流版" aria-label="Permalink to &quot;省流版&quot;">​</a></h2><p>如果不想看长文，按下面三步走即可跑起来：</p><div class="x-steps"><ul><li><strong>启动程序</strong>：双击 <code>Start</code> 运行，仔细阅读弹出的用户须知，然后进入设置页面。</li><li><strong>填写并保存</strong>：填写账号密码与课程名称，按需选择功能选项，最后<strong>务必点击“保存”</strong>。</li><li><strong>开始刷课</strong>：返回“主页”，点击“开始刷课”，脚本会自动打开浏览器登录你的学习通并开始运行。</li></ul></div><p>有疑问的话，继续往下看详细介绍。</p><h2 id="_1-启动程序" tabindex="-1">1. 启动程序 <a class="header-anchor" href="#_1-启动程序" aria-label="Permalink to &quot;1. 启动程序&quot;">​</a></h2><p>双击 <code>Start</code> 运行。运行后会出现一个弹窗，请仔细阅读用户须知，然后进入到设置页面填写相关信息。</p><h2 id="_2-配置设置" tabindex="-1">2. 配置设置 <a class="header-anchor" href="#_2-配置设置" aria-label="Permalink to &quot;2. 配置设置&quot;">​</a></h2><div class="x-figure"><figcaption>设置页面总览</figcaption><img src="'+n+'" alt="设置页面"></div><p>设置页面中的第一项为<strong>配置设置</strong>，已经填充好了内容，不用修改。</p><p>但如果在开始刷课后有提示浏览器相关的报错，就需要修改，具体操作见 <a href="./driver.html">如何安装正确的驱动</a>。</p><div class="tip custom-block"><p class="custom-block-title">小提示</p><p>选择 <strong>Edge</strong> 浏览器后驱动地址会自动填充，是最省事的选择。报错了再去看驱动安装那一章。</p></div><h2 id="_3-界面设置" tabindex="-1">3. 界面设置 <a class="header-anchor" href="#_3-界面设置" aria-label="Permalink to &quot;3. 界面设置&quot;">​</a></h2><p>第二项为<strong>界面设置</strong>，可根据个人喜好自行调整。</p><h2 id="_4-账号信息" tabindex="-1">4. 账号信息 <a class="header-anchor" href="#_4-账号信息" aria-label="Permalink to &quot;4. 账号信息&quot;">​</a></h2><p>第三项为<strong>账号信息</strong>，需要注意三点：</p><ul><li>需要将你登录学习通的账号密码填写到输入框中；</li><li>然后填写要刷课的名称，<strong>可以添加课程，不过最多只能连续刷 3 门课程</strong>；</li><li>如果你不想使用账号密码登录，也可以在账号密码一栏中随意填写，在开始刷课后会提示你进行<strong>扫码登录</strong>。</li></ul><h2 id="_5-功能设置" tabindex="-1">5. 功能设置 <a class="header-anchor" href="#_5-功能设置" aria-label="Permalink to &quot;5. 功能设置&quot;">​</a></h2><p>第四项为<strong>功能设置</strong>，根据实际需求自行选择：</p><ul><li>前两项功能已经开发完毕；</li><li>最后一项还在开发中。</li></ul><h3 id="_5-1-章节测验" tabindex="-1">5.1 章节测验 <a class="header-anchor" href="#_5-1-章节测验" aria-label="Permalink to &quot;5.1 章节测验&quot;">​</a></h3><p>第一个是“章节测验”，也就是章节中的测试题。点击下拉框有三个选择，根据自己的实际需求自行选择。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>“随机答题”请谨慎选择，只有在章节测验<strong>不计入总成绩</strong>的情况下才能使用，否则成绩会很低。</p></div><p>如果你没有选择“不刷题”，则会弹出一个答完题后的设置，根据实际需求自行选择。</p><h3 id="_5-2-视频弹题" tabindex="-1">5.2 视频弹题 <a class="header-anchor" href="#_5-2-视频弹题" aria-label="Permalink to &quot;5.2 视频弹题&quot;">​</a></h3><p>第二个是视频中间弹出的题目的作答方式，也有两个选择，根据实际需求自行选择。</p><h3 id="_5-3-讨论部分" tabindex="-1">5.3 讨论部分 <a class="header-anchor" href="#_5-3-讨论部分" aria-label="Permalink to &quot;5.3 讨论部分&quot;">​</a></h3><p>第三个是讨论部分的完成方式，同样也有两个选择，根据实际需求自行选择。</p><h3 id="_5-4-倍数设置" tabindex="-1">5.4 倍数设置 <a class="header-anchor" href="#_5-4-倍数设置" aria-label="Permalink to &quot;5.4 倍数设置&quot;">​</a></h3><p>第四个是“倍数设置”，<strong>建议设置为 2 倍速</strong>，否则倍速过高，有可能会导致学习通已完成的任务点被清空。</p><h3 id="_5-5-跳过人脸" tabindex="-1">5.5 跳过人脸 <a class="header-anchor" href="#_5-5-跳过人脸" aria-label="Permalink to &quot;5.5 跳过人脸&quot;">​</a></h3><p>若课程需要刷脸才能进入，可开启此功能。开启后，第一次刷课需用手机扫码进行人脸验证，之后刷课就会自动跳过。</p><h3 id="_5-6-多端学习" tabindex="-1">5.6 多端学习 <a class="header-anchor" href="#_5-6-多端学习" aria-label="Permalink to &quot;5.6 多端学习&quot;">​</a></h3><p>开启后可同时刷多门课程，但<strong>请谨慎开启</strong>。</p><div class="danger custom-block"><p class="custom-block-title">风险提示</p><p>开启后有可能清空课程进度，甚至直接挂科。如果不是实在刷不完，还请老老实实一科一科地刷，<strong>一切后果自负</strong>。</p></div><h3 id="_5-7-秒过视频" tabindex="-1">5.7 秒过视频 <a class="header-anchor" href="#_5-7-秒过视频" aria-label="Permalink to &quot;5.7 秒过视频&quot;">​</a></h3><p>只有在视频<strong>可以拖动进度条</strong>的情况下生效。</p><h3 id="_5-8-防锁屏" tabindex="-1">5.8 防锁屏 <a class="header-anchor" href="#_5-8-防锁屏" aria-label="Permalink to &quot;5.8 防锁屏&quot;">​</a></h3><p>开启后在刷课的途中鼠标会左右跳动，防止电脑息屏影响刷课。当然，你也可以自行在电脑系统设置中关闭息屏功能。</p><h3 id="_5-9-定时刷课" tabindex="-1">5.9 定时刷课 <a class="header-anchor" href="#_5-9-定时刷课" aria-label="Permalink to &quot;5.9 定时刷课&quot;">​</a></h3><p>开启后在不关闭脚本窗口的情况下，可以根据你设定的时间，定时开始刷课或者结束刷课。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>开启后脚本窗口<strong>一定不能关闭</strong>，否则无法正常定时刷课。</p></div><h2 id="_6-关于自动完成作业功能" tabindex="-1">6. 关于自动完成作业功能 <a class="header-anchor" href="#_6-关于自动完成作业功能" aria-label="Permalink to &quot;6. 关于自动完成作业功能&quot;">​</a></h2><h3 id="_6-1-ai-答题" tabindex="-1">6.1 AI 答题 <a class="header-anchor" href="#_6-1-ai-答题" aria-label="Permalink to &quot;6.1 AI 答题&quot;">​</a></h3><p>选择该功能后，将<strong>强制使用 DeepSeek AI</strong> 作为作业的答题方式，并自动保存答案。</p><div class="tip custom-block"><p class="custom-block-title">使用前提</p><p>需要先在设置中配置好 <strong>DeepSeek API 密钥</strong>，否则无法正常答题。</p></div><h3 id="_6-2-选择作业" tabindex="-1">6.2 选择作业 <a class="header-anchor" href="#_6-2-选择作业" aria-label="Permalink to &quot;6.2 选择作业&quot;">​</a></h3><p>关于“选择作业”，也有两个选择：</p><ul><li><strong>手动选择</strong>：进入到作业页面后，你需要手动点击要刷的作业，刷完该作业后程序会自动结束；</li><li><strong>自动选择</strong>：则默认从第 1 个作业开始，依次刷至最后一个。</li></ul><p>该章节中后面两个功能的详细说明，可以回看前面的小节：</p><ul class="x-anchor-nav"><li><a href="#_5-5-跳过人脸">5.5 跳过人脸</a></li><li><a href="#_5-6-多端学习">5.6 多端学习</a></li></ul><h2 id="_7-保存设置" tabindex="-1">7. 保存设置 <a class="header-anchor" href="#_7-保存设置" aria-label="Permalink to &quot;7. 保存设置&quot;">​</a></h2><p>填写完信息后<strong>务必点击“保存”</strong>，否则无法刷课。同样，修改任何信息都要进行保存，否则修改无效。</p><h2 id="_8-开始刷课" tabindex="-1">8. 开始刷课 <a class="header-anchor" href="#_8-开始刷课" aria-label="Permalink to &quot;8. 开始刷课&quot;">​</a></h2><p>保存好信息后返回“主页”，点击“开始刷课”，脚本会自动打开浏览器登录你的学习通，进行自动刷课。</p><p>你也可以选择<strong>定时刷课</strong>，程序会自动按照你设定的时间开始或结束刷课。开启定时刷课后脚本的窗口不能关闭，否则无法定时开启刷课。</p><div class="x-keyline"><p>🚑 <strong>卡住了？</strong>如果开始刷课时弹出报错窗口，请前往 <a href="./faq">四、报错了该怎么办</a>；如果是浏览器驱动相关的报错，请看 <a href="./driver">三、如何安装正确的驱动</a>。</p></div><hr>',57))])}const q=e(h,[["render",d]]);export{m as __pageData,q as default};
